         this.stream.publish({
           type: "notification.updated",
           notification: {
             ...notification,
             status: "sent",
             sentAt,
             updatedAt: sentAt,
           },
         });

         logger.info(
           `Notification sent for transaction ${event.transactionId} to ${userEmail}`
         );
       } catch (emailError) {
         // Mark notification as failed
         await this.notificationRepository.updateStatus(
           notification.id,
           "failed"
         );
         const updatedAt = new Date();
         this.stream.publish({
           type: "notification.updated",
           notification: {
             ...notification,
             status: "failed",
             updatedAt,
           },
         });

         logger.error(
           `Failed to send notification email for transaction ${event.transactionId}`,
           emailError
         );
       }
     } catch (error) {
       logger.error(
         `Error handling transaction event ${event.transactionId}`,
         error
       );
       // Don't throw - let consumer continue processing
     }
   }
 }

